class MyHashMap:
    def __init__(self):
        self.size = 0
        self.buckets = [[] for _ in range(8)]

    def _bucket(self, key: int) -> list:
        return self.buckets[hash(key) % len(self.buckets)]

    def put(self, key: int, value: int) -> None:
        b = self._bucket(key)
        for pair in b:
            if pair[0] == key:
                pair[1] = value
                return
        b.append([key, value])
        self.size += 1
        if self.size > 2 * len(self.buckets):       # load factor > 2: double and rehash
            self._resize()

    def get(self, key: int) -> int:
        for k, v in self._bucket(key):
            if k == key:
                return v
        return -1

    def remove(self, key: int) -> None:
        b = self._bucket(key)
        for i, (k, _) in enumerate(b):
            if k == key:
                b.pop(i)
                self.size -= 1
                return

    def _resize(self) -> None:
        old = self.buckets
        self.buckets = [[] for _ in range(2 * len(old))]
        for b in old:
            for k, v in b:
                self.buckets[hash(k) % len(self.buckets)].append([k, v])

