def brute_force(s: str) -> int:
    """Slice out sign and digit run, convert with int(), then clamp; O(n) extra space."""
    s = s.lstrip(" ")
    sign = 1
    if s[:1] in ("+", "-"):
        sign = -1 if s[0] == "-" else 1
        s = s[1:]
    digits = ""
    for ch in s:
        if not "0" <= ch <= "9":
            break
        digits += ch
    value = sign * int(digits) if digits else 0
    return max(-2**31, min(2**31 - 1, value))

