class Solution:
    def myAtoi(self, s: str) -> int:
        INT_MAX, INT_MIN = 2**31 - 1, -2**31
        i, n = 0, len(s)
        while i < n and s[i] == " ":
            i += 1
        sign = 1
        if i < n and s[i] in "+-":
            sign = -1 if s[i] == "-" else 1
            i += 1
        num = 0
        while i < n and "0" <= s[i] <= "9":
            num = num * 10 + (ord(s[i]) - 48)
            if sign * num >= INT_MAX:          # clamp as soon as the bound is crossed
                return INT_MAX
            if sign * num <= INT_MIN:
                return INT_MIN
            i += 1
        return sign * num

