class Solution:
    def convert(self, s: str, numRows: int) -> str:
        if numRows == 1 or numRows >= len(s):
            return s
        rows = [[] for _ in range(numRows)]
        r, step = 0, 1
        for ch in s:
            rows[r].append(ch)
            if r == 0:
                step = 1                   # bounce off the top
            elif r == numRows - 1:
                step = -1                  # bounce off the bottom
            r += step
        return "".join("".join(row) for row in rows)

