class Solution:
    def groupStrings(self, strings: List[str]) -> List[List[str]]:
        groups = defaultdict(list)
        for s in strings:
            key = tuple((ord(b) - ord(a)) % 26 for a, b in zip(s, s[1:]))   # shift-invariant
            groups[key].append(s)
        return list(groups.values())

